func readStrictDomainVersions(r *strictjson.TypedReader, v *domain.Versions) {
	object := r.Object()
	var seen uint64
	for object.Next() {
		var bit uint64
		switch string(object.Key) {
		case "site":
			bit = 1
		case "board":
			bit = 2
		case "thread":
			bit = 4
		case "cap":
			bit = 8
		default:
			r.Reject()
			return
		}
		if seen&bit != 0 {
			r.Reject()
			return
		}
		seen |= bit
		switch bit {
		case 1:
			v.Site = domain.U64(r.UintString())
		case 2:
			v.Board = domain.U64(r.UintString())
		case 4:
			v.Thread = domain.U64(r.UintString())
		case 8:
			if !r.Null() {
				v.Cap = new(domain.U64)
				(*(v.Cap)) = domain.U64(r.UintString())
			}
		}
	}
	r.Require(seen&15 == 15)
}

// readStrictPostcaptureDisplay はDisplayの完全キー集合と値を私的候補へ復号する。
func readStrictPostcaptureDisplay(r *strictjson.TypedReader, v *Display) {
	object := r.Object()
	var seen uint64
	for object.Next() {
		var bit uint64
		switch string(object.Key) {
		case "noname":
			bit = 1
		case "force_noname":
			bit = 2
		case "hide_mail":
			bit = 4
		default:
			r.Reject()
			return
		}
		if seen&bit != 0 {
			r.Reject()
			return
		}
		seen |= bit
		switch bit {
		case 1:
			v.Noname = string(r.String())
		case 2:
			v.ForceNoname = bool(r.Bool())
		case 4:
			v.HideMail = bool(r.Bool())
		}
	}
	r.Require(seen&7 == 7)
}
